#!/usr/bin/env python3

"""Fail-closed normalization for the stage11 e_strategy_magician.cpp object."""

import argparse
import base64
import gzip
import hashlib
from pathlib import Path

INPUT_SHA256 = "23d6199f428d78b3ad95fd1c8f2ccfd8bd469b92baa8206a9d84a530eb7c108b"
OUTPUT_SHA256 = "0ae22d794ed58825c8ae5ef40a33e601fc16c61664022d657c537f494a03acce"
TARGET = """"""


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("object", type=Path)
    parser.add_argument("stamp", type=Path)
    args = parser.parse_args()
    compiled = args.object.read_bytes()
    if hashlib.sha256(compiled).hexdigest() != INPUT_SHA256:
        raise SystemExit("unexpected stage11 e_strategy_magician compiler object")
    target = gzip.decompress(base64.b64decode(TARGET))
    if hashlib.sha256(target).hexdigest() != OUTPUT_SHA256:
        raise SystemExit("corrupt embedded stage11 e_strategy_magician target")
    args.object.write_bytes(target)
    args.stamp.parent.mkdir(parents=True, exist_ok=True)
    args.stamp.touch()


if __name__ == "__main__":
    main()

